int FUL_tape_validate(const FUL_tape *tape) {
  size_t i;
  if(!tape || tape->size>tape->capacity || (tape->size && !tape->data)) return -1;
  for(i=0;i<tape->size;++i) if(FUL_vw_validate_instruction(&tape->data[i],tape->size)) return -4;
  return 0;
}

/* .frame */
int FUL_call(FUL_vm *vm, FUL_cell target) {
  FUL_activation *frame;
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if((uintmax_t)target>=vm->vw_code_size) { FUL_vw_fail(vm,-4); return -4; }
  if(vm->vw_frame_count>=sizeof(vm->vw_frames)/sizeof(vm->vw_frames[0])) { FUL_vw_fail(vm,-3); return -3; }
  frame=&vm->vw_frames[vm->vw_frame_count++]; memset(frame,0,sizeof(*frame));
  frame->return_address=vm->vw_pc; frame->stack_base=vm->vw_sp; vm->vw_pc=(size_t)target; return 0;
}
int FUL_ret(FUL_vm *vm) {
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if(!vm->vw_frame_count) { FUL_vw_fail(vm,-2); return -2; }
  vm->vw_pc=vm->vw_frames[--vm->vw_frame_count].return_address; return 0;
}
